import React, { useState, useEffect } from "react";
import { FiAlertTriangle, FiAlertCircle, FiEdit, FiTrash2, FiX } from "react-icons/fi";
import { useNavigate } from "react-router-dom";
import toast from "react-hot-toast";
import DeleteModal from "../../Modals/DeleteModal";

const InventoryTab = ({ activeSub }) => {
  const [currentSubTab, setCurrentSubTab] = useState("inventory-list");
  const navigate = useNavigate();

  useEffect(() => {
    if (activeSub === "inventory-list") setCurrentSubTab("inventory-list");
    else if (activeSub === "stock-alerts") setCurrentSubTab("stock-alerts");
  }, [activeSub]);

  // Initial Inventory Mock Data State
  const [inventoryData, setInventoryData] = useState([
    { id: 1, name: "Paracetamol 650mg",  stock: 15, reserved: 2, available: 13, expiry: "2027-12-31", threshold: 50, status: "Low Stock" },
    { id: 2, name: "Amoxicillin 500mg", stock: 8, reserved: 0, available: 8, expiry: "2027-08-30", threshold: 30, status: "Low Stock" },
    { id: 3, name: "Metformin 500mg", stock: 0, reserved: 0, available: 0, expiry: "2026-07-31", threshold: 20, status: "Out of Stock" },
    { id: 4, name: "Vicks Vaporub",  stock: 45, reserved: 5, available: 40, expiry: "2026-09-30", threshold: 15, status: "In Stock" },
    { id: 5, name: "Atorvastatin 10mg", stock: 12, reserved: 0, available: 12, expiry: "2026-08-15", threshold: 10, status: "In Stock" },
    { id: 6, name: "Expired Vitamin C Tablets", stock: 15, reserved: 0, available: 15, expiry: "2025-05-10", threshold: 20, status: "Expired" },
  ]);

  const [filterReason, setFilterReason] = useState("All");
  const [filterStatus, setFilterStatus] = useState("All");
  const [editingItem, setEditingItem] = useState(null);
  const [deletingItem, setDeletingItem] = useState(null);
  const [editForm, setEditForm] = useState({
    stock: 0,
    threshold: 0,
    expiry: "",
  });
  const [searchQuery, setSearchQuery] = useState("");
  const [expiryFilter, setExpiryFilter] = useState("All");

  const handleSaveEdit = (e) => {
    e.preventDefault();
    setInventoryData(
      inventoryData.map((item) => {
        if (item.id === editingItem.id) {
          const newStock = parseInt(editForm.stock) || 0;
          const newThreshold = parseInt(editForm.threshold) || 0;
          const newAvailable = Math.max(0, newStock - item.reserved);
          
          // Determine status
          let newStatus = "In Stock";
          const today = new Date("2026-06-23");
          const expDate = new Date(editForm.expiry);
          if (expDate < today) {
            newStatus = "Expired";
          } else if (newStock === 0) {
            newStatus = "Out of Stock";
          } else if (newStock < newThreshold) {
            newStatus = "Low Stock";
          }
          
          return {
            ...item,
            stock: newStock,
            threshold: newThreshold,
            available: newAvailable,
            expiry: editForm.expiry,
            status: newStatus,
          };
        }
        return item;
      })
    );
    toast.success(`${editingItem.name} updated successfully.`);
    setEditingItem(null);
  };

  const handleConfirmDelete = () => {
    setInventoryData(inventoryData.filter((item) => item.id !== deletingItem.id));
    toast.success(`${deletingItem.name} deleted successfully.`);
    setDeletingItem(null);
  };

  // Derive Alerts (low stock or expired or out of stock)
  const alertsData = inventoryData
    .filter((item) => item.status === "Low Stock" || item.status === "Out of Stock" || item.status === "Expired")
    .filter((item) => {
      if (filterReason === "All") return true;
      return item.status === filterReason;
    });

  const filteredInventoryData = inventoryData
    .filter((item) => {
      if (filterStatus === "All") return true;
      return item.status === filterStatus;
    })
    .filter((item) => {
      if (!searchQuery) return true;
      const displayId = (99 + item.id).toString();
      return (
        item.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        displayId.includes(searchQuery)
      );
    })
    .filter((item) => {
      if (expiryFilter === "All") return true;
      const today = new Date("2026-06-23");
      const expDate = new Date(item.expiry);
      if (expiryFilter === "Expired") {
        return expDate < today;
      }
      if (expiryFilter === "Near Expiry") {
        const diffTime = expDate - today;
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
        return diffDays >= 0 && diffDays <= 90;
      }
      if (expiryFilter === "Active") {
        return expDate >= today;
      }
      return true;
    });

  return (
    <div className="inventory-tab animate-fade-in">
      
      {/* Sub tabs switcher */}
      <div className="d-flex justify-content-between align-items-center flex-wrap mb-4 gap-3">
        <h3 style={{ fontSize: "22px", fontWeight: "800", color: "#0F172A", margin: 0 }}>
          Inventory Management
        </h3>
        <div className="d-flex gap-2" style={{ backgroundColor: "#F1F5F9", padding: "4px", borderRadius: "8px" }}>
          {[
            { id: "inventory-list", label: "Inventory List", path: "/seller-dashboard/inventory-list" },
            { id: "stock-alerts", label: "Stock Alerts", path: "/seller-dashboard/stock-alerts" },
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => navigate(tab.path)}
              style={{
                border: "none",
                background: currentSubTab === tab.id ? "#ffffff" : "transparent",
                color: currentSubTab === tab.id ? "#A847F0" : "#64748B",
                padding: "8px 16px",
                borderRadius: "6px",
                fontSize: "13px",
                fontWeight: "700",
                boxShadow: currentSubTab === tab.id ? "0 1px 3px rgba(0,0,0,0.05)" : "none",
                cursor: "pointer",
                transition: "all 0.2s",
              }}
            >
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      {currentSubTab === "inventory-list" && (
        <div className="dashboard-card p-4">
          <div className="d-flex justify-content-between align-items-center flex-wrap gap-3 mb-4">
            <h4 style={{ fontSize: "16px", fontWeight: "700", color: "#0F172A", margin: 0 }}>
              Warehouse Inventory Stock ({filteredInventoryData.length})
            </h4>
            <div className="d-flex align-items-center flex-wrap gap-3">
              {/* Search Bar */}
              <div style={{ position: "relative", width: "180px" }}>
                <input
                  type="text"
                  placeholder="Search products..."
                  className="form-control"
                  style={{
                    height: "36px",
                    borderRadius: "8px",
                    fontSize: "13px",
                    paddingRight: "28px",
                    borderColor: "#CBD5E1",
                    boxShadow: "none"
                  }}
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
                {searchQuery && (
                  <button
                    type="button"
                    onClick={() => setSearchQuery("")}
                    style={{
                      position: "absolute",
                      right: "8px",
                      top: "50%",
                      transform: "translateY(-50%)",
                      border: "none",
                      background: "none",
                      color: "#94A3B8",
                      cursor: "pointer",
                      padding: 0
                    }}
                  >
                    <FiX size={14} />
                  </button>
                )}
              </div>

              {/* Status Filter */}
              <div className="d-flex align-items-center gap-2">
                <label style={{ fontSize: "13px", fontWeight: "600", color: "#64748B", margin: 0 }}>Status:</label>
                <select
                  className="form-select border shadow-none"
                  style={{ height: "36px", width: "120px", borderRadius: "8px", fontSize: "13px" }}
                  value={filterStatus}
                  onChange={(e) => setFilterStatus(e.target.value)}
                >
                  <option value="All">All Statuses</option>
                  <option value="In Stock">In Stock</option>
                  <option value="Low Stock">Low Stock</option>
                  <option value="Out of Stock">Out of Stock</option>
                  <option value="Expired">Expired</option>
                </select>
              </div>

              {/* Expiry Filter */}
              <div className="d-flex align-items-center gap-2">
                <label style={{ fontSize: "13px", fontWeight: "600", color: "#64748B", margin: 0 }}>Expiry:</label>
                <select
                  className="form-select border shadow-none"
                  style={{ height: "36px", width: "120px", borderRadius: "8px", fontSize: "13px" }}
                  value={expiryFilter}
                  onChange={(e) => setExpiryFilter(e.target.value)}
                >
                  <option value="All">All Expiries</option>
                  <option value="Active">Not Expired</option>
                  <option value="Near Expiry">Near Expiry (90d)</option>
                  <option value="Expired">Expired</option>
                </select>
              </div>
            </div>
          </div>
          <div className="table-responsive">
            <table className="table align-middle">
              <thead className="table-light">
                <tr style={{ fontSize: "12px", color: "#475569", fontWeight: "700" }}>
                  <th>Product ID</th>
                  <th>Product Name</th>
                  {/* <th>SKU Code</th> */}
                  <th>Stock Quantity</th>
                  <th>Reserved Quantity</th>
                  <th>Available Quantity</th>
                  <th>Expiry Date</th>
                  <th>Stock Status</th>
                  <th className="text-center">Action</th>
                </tr>
              </thead>
              <tbody>
                {filteredInventoryData.map((item, idx) => (
                  <tr key={idx} style={{ fontSize: "13px", color: "#334155" }}>
                    <td>
                      <span className="text-secondary small fw-600">#{99 + item.id}</span>
                    </td>
                    <td className="fw-700">{item.name}</td>
                    {/* <td className="font-monospace text-secondary" style={{ fontSize: "12px" }}>{item.sku}</td> */}
                    <td className="fw-600">{item.stock}</td>
                    <td className="text-muted">{item.reserved}</td>
                    <td className="fw-800 text-heading">{item.available}</td>
                    <td className={`fw-600 ${item.status === "Expired" ? "text-danger" : ""}`}>{item.expiry}</td>
                    <td>
                      <span
                        className={`badge rounded-pill ${
                          item.status === "In Stock"
                            ? "bg-success-subtle text-success"
                            : item.status === "Low Stock"
                            ? "bg-warning-subtle text-warning"
                            : item.status === "Expired" || item.status === "Out of Stock"
                            ? "bg-danger-subtle text-danger"
                            : "bg-light text-secondary"
                        } px-2.5 py-1`}
                      >
                        {item.status}
                      </span>
                    </td>
                    <td>
                      <div className="d-flex gap-2 align-items-center justify-content-center">
                        <button
                          onClick={() => {
                            setEditingItem(item);
                            setEditForm({
                              stock: item.stock,
                              threshold: item.threshold,
                              expiry: item.expiry,
                            });
                          }}
                          className="btn-action btn-view"
                          title="Edit Inventory"
                        >
                          <FiEdit size={13} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {currentSubTab === "stock-alerts" && (
        <div className="dashboard-card p-4">
          <div className="d-flex justify-content-between align-items-center flex-wrap gap-3 mb-4">
            <h4 style={{ fontSize: "16px", fontWeight: "700", color: "#0F172A", margin: 0 }}>
              Active Stock Alerts
            </h4>
            <div className="d-flex align-items-center gap-2">
              <label style={{ fontSize: "13px", fontWeight: "600", color: "#64748B", margin: 0 }}>Reason:</label>
              <select
                className="form-select border shadow-none"
                style={{ height: "36px", width: "160px", borderRadius: "8px", fontSize: "13px" }}
                value={filterReason}
                onChange={(e) => setFilterReason(e.target.value)}
              >
                <option value="All">All Reasons</option>
                <option value="Low Stock">Low Stock</option>
                <option value="Out of Stock">Out of Stock</option>
                <option value="Expired">Expired</option>
              </select>
            </div>
          </div>

          <div className="table-responsive">
            <table className="table align-middle">
              <thead className="table-light">
                <tr style={{ fontSize: "12px", color: "#475569", fontWeight: "700" }}>
                  <th>Product Name</th>
                  <th>Current Stock</th>
                  <th>Threshold</th>
                  <th>Expiry Date</th>
                  <th>Alert Reason</th>
                  <th className="text-center">Action</th>                </tr>
              </thead>
              <tbody>
                {alertsData.map((alert, idx) => (
                  <tr key={idx} style={{ fontSize: "13px", color: "#334155" }}>
                    <td className="fw-700">
                      <div className="d-flex align-items-center gap-2">
                        {alert.status === "Expired" ? (
                          <FiAlertCircle size={16} color="#EF4444" />
                        ) : (
                          <FiAlertTriangle size={16} color="#D97706" />
                        )}
                        <span>{alert.name}</span>
                      </div>
                    </td>
                    <td className="fw-700">{alert.stock} Units</td>
                    <td className="text-muted">{alert.threshold} Units</td>
                    <td className={`fw-600 ${alert.status === "Expired" ? "text-danger" : ""}`}>{alert.expiry}</td>
                    <td>
                      <span
                        className={`badge rounded-pill ${
                          alert.status === "Expired" || alert.status === "Out of Stock"
                            ? "bg-danger-subtle text-danger"
                            : "bg-warning-subtle text-warning"
                        } px-2.5 py-1`}
                      >
                        {alert.status}
                      </span>
                    </td>
                    <td>
                      <div className="d-flex gap-2 align-items-center justify-content-center flex-wrap">
                        <button
                          className="btn btn-sm rounded-pill px-3"
                          style={{
                            fontSize: "11px",
                            fontWeight: "700",
                            backgroundColor: alert.status === "Expired" ? "#EF4444" : "#10B981",
                            color: "#ffffff",
                            border: "none"
                          }}
                          onClick={() => {
                            if (alert.status === "Expired") {
                              toast.success(`Marked ${alert.name} for disposal.`);
                            } else {
                              toast.success(`Initiated restock request for ${alert.name}.`);
                            }
                          }}
                        >
                          {alert.status === "Expired" ? "Dispose" : "Restock"}
                        </button>
                        
                        <button
                          onClick={() => {
                            setEditingItem(alert);
                            setEditForm({
                              stock: alert.stock,
                              threshold: alert.threshold,
                              expiry: alert.expiry,
                            });
                          }}
                          className="btn-action btn-view"
                          title="Edit Alert"
                        >
                          <FiEdit size={13} />
                        </button>

                        <button
                          onClick={() => setDeletingItem(alert)}
                          className="btn-action btn-reject"
                          title="Delete Alert"
                        >
                          <FiTrash2 size={13} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* EDIT ALERT MODAL */}
      {editingItem && (
        <div className="dashboard-modal-overlay">
          <div className="dashboard-modal-content">
            <div className="d-flex justify-content-between align-items-center mb-4 pb-2 border-bottom">
              <h4 className="mb-0 text-heading fw-800">Update Stock Alert</h4>
              <button onClick={() => setEditingItem(null)} className="btn-close-modal">
                <FiX size={20} />
              </button>
            </div>
            
            <form onSubmit={handleSaveEdit}>
              <div className="row gy-3">
                <div className="col-12">
                  <div className="p-3 bg-light rounded-3 mb-2">
                    <span className="text-muted small d-block">Alert Product</span>
                    <strong className="text-heading font-16">{editingItem.name}</strong>
                  </div>
                </div>

                <div className="col-md-6">
                  <label className="form-label fw-700 text-heading mb-1 small">Stock Quantity</label>
                  <input
                    type="number"
                    required
                    className="common-input border"
                    value={editForm.stock}
                    onChange={(e) => setEditForm({ ...editForm, stock: e.target.value })}
                  />
                </div>

                <div className="col-md-6">
                  <label className="form-label fw-700 text-heading mb-1 small">Safety Threshold</label>
                  <input
                    type="number"
                    required
                    className="common-input border"
                    value={editForm.threshold}
                    onChange={(e) => setEditForm({ ...editForm, threshold: e.target.value })}
                  />
                </div>

                <div className="col-12">
                  <label className="form-label fw-700 text-heading mb-1 small">Expiry Date</label>
                  <input
                    type="date"
                    required
                    className="common-input border"
                    value={editForm.expiry}
                    onChange={(e) => setEditForm({ ...editForm, expiry: e.target.value })}
                  />
                </div>
              </div>

              <div className="d-flex justify-content-end gap-2 mt-4 pt-3 border-top">
                <button
                  type="button"
                  onClick={() => setEditingItem(null)}
                  className="btn btn-light pill px-4"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="btn btn-main pill px-4"
                  style={{ backgroundColor: "#A847F0", color: "white", border: "none" }}
                >
                  Save Changes
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      <DeleteModal
        open={!!deletingItem}
        title="Delete Stock Alert?"
        itemName={deletingItem?.name}
        message="This action will remove the item from active alerts. Are you sure you want to delete this alert?"
        onClose={() => setDeletingItem(null)}
        onConfirm={handleConfirmDelete}
      />

      <style>{`
        .btn-action {
          width: 32px;
          height: 32px;
          border-radius: 6px;
          border: none;
          display: inline-flex;
          align-items: center;
          justify-content: center;
          cursor: pointer;
          transition: all 0.2s;
        }
        .btn-view {
          background-color: #EFF6FF;
          color: #3B82F6;
        }
        .btn-view:hover {
          background-color: #3B82F6;
          color: #ffffff;
        }
        .btn-reject {
          background-color: #FFF1F2;
          color: #F43F5E;
        }
        .btn-reject:hover {
          background-color: #F43F5E;
          color: #ffffff;
        }

        /* Modal styling */
        .dashboard-modal-overlay {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background-color: rgba(15, 23, 42, 0.6);
          backdrop-filter: blur(4px);
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 9999;
          padding: 15px;
        }
        .dashboard-modal-content {
          background-color: #ffffff;
          border-radius: 16px;
          width: 100%;
          max-width: 520px;
          padding: 28px;
          box-shadow: 0 20px 25px -5px rgba(0,0,0,0.1), 0 10px 10px -5px rgba(0,0,0,0.04);
        }
        .btn-close-modal {
          border: none;
          background: none;
          color: #64748B;
          cursor: pointer;
          display: flex;
          align-items: center;
          justify-content: center;
          padding: 4px;
          border-radius: 50%;
          transition: all 0.2s;
        }
        .btn-close-modal:hover {
          background-color: #F1F5F9;
          color: #0F172A;
        }
      `}</style>

    </div>
  );
};

export default InventoryTab;
