// DeleteModal.jsx
import React from "react";
import { FiTrash2 } from "react-icons/fi";

const DeleteModal = ({
  open,
  title = "Delete Item?",
  message = "Are you sure you want to delete this item?",
  itemName = "",
  onClose,
  onConfirm,
}) => {
  if (!open) return null;

  return (
    <>
      <div className="dashboard-modal-overlay">
        <div className="delete-modal-box">
          <div className="text-center">
            <div className="delete-icon-box">
              <FiTrash2 size={28} color="#DC2626" />
            </div>

            <h4>{title}</h4>
            <p className="mb-3">{message}</p>

            {itemName && (
              <div
                style={{
                  backgroundColor: "#F8FAFC",
                  border: "1px dashed #E2E8F0",
                  padding: "10px 14px",
                  borderRadius: "8px",
                  fontWeight: "700",
                  color: "#0F172A",
                  fontSize: "14px",
                  marginBottom: "20px",
                  display: "inline-block",
                  wordBreak: "break-all"
                }}
              >
                {itemName}
              </div>
            )}

            <div className="d-flex justify-content-center gap-2">
              <button onClick={onClose} className="btn btn-light px-4">
                Cancel
              </button>

              <button onClick={onConfirm} className="btn btn-danger px-4">
                Delete
              </button>
            </div>
          </div>
        </div>
      </div>

      <style>{`
        .dashboard-modal-overlay {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background-color: rgba(15, 23, 42, 0.5);
          backdrop-filter: blur(2px);
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 99999;
          padding: 15px;
          pointer-events: none;
        }
        .delete-modal-box {
          background-color: #ffffff;
          border-radius: 16px;
          width: 100%;
          max-width: 400px;
          padding: 30px;
          box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.15), 0 10px 10px -5px rgba(0, 0, 0, 0.05);
          animation: modalScale 0.2s ease-out;
          pointer-events: auto;
        }
        .delete-icon-box {
          width: 56px;
          height: 56px;
          border-radius: 50%;
          background-color: #FEE2E2;
          display: inline-flex;
          align-items: center;
          justify-content: center;
          margin-bottom: 16px;
        }
        .delete-modal-box h4 {
          font-size: 18px;
          font-weight: 800;
          color: #0F172A;
          margin-bottom: 8px;
        }
        .delete-modal-box p {
          font-size: 13px;
          color: #64748B;
          margin-bottom: 24px;
        }
        .delete-modal-box .btn {
          border-radius: 30px;
          font-size: 13px;
          font-weight: 700;
        }
        @keyframes modalScale {
          from {
            transform: scale(0.95);
            opacity: 0;
          }
          to {
            transform: scale(1);
            opacity: 1;
          }
        }
      `}</style>
    </>
  );
};

export default DeleteModal;